using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.Linq;using TMPro;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckCornhole.Editor {
public static class CornholeWeatherAuthoring {
 [MenuItem("Truck Sports/Cornhole/Repair viewport sky coverage")]
 public static void UpgradeViewportSky(){EditorSceneManager.OpenScene(CornholeAuthoring.Scene);var match=Object.FindAnyObjectByType<CornholeMatch>();SportsWeatherRenderingAuthoring.UseViewportSkybox(match.gameObject,match.courses.Select(course=>course.chase.view).ToArray(),"TruckCornhole");EditorSceneManager.MarkSceneDirty(match.gameObject.scene);EditorSceneManager.SaveScene(match.gameObject.scene);AssetDatabase.SaveAssets();Debug.Log("CORNHOLE_SKY: documented Weather Maker skybox path; four camera clear modes and sky/cloud render configuration only. Physics, throwing, scoring, wind and venue untouched.");}
 public static void Upgrade(){EditorSceneManager.OpenScene(CornholeAuthoring.Scene);var m=UnityEngine.Object.FindAnyObjectByType<CornholeMatch>();Install(m);EditorSceneManager.MarkSceneDirty(m.gameObject.scene);EditorSceneManager.SaveScene(m.gameObject.scene);AssetDatabase.SaveAssets();}
 public static void Install(CornholeMatch m){var cameras=m.courses.Select(course=>course.chase.view).ToArray();if(m.atmosphere==null)m.atmosphere=SportsChaosAuthoring.Weather(m.gameObject,cameras,"TruckCornhole");m.weatherPresets=SportsWeatherPresetsAuthoring.EnsureCatalog();m.atmosphere.presets=m.weatherPresets;m.atmosphere.cornhole=m;SportsWeatherRenderingAuthoring.Install(m.gameObject,cameras,"TruckCornhole");SportsSnowAuthoring.InstallScene();var picker=SportsWeatherPickerAuthoring.Install(m.menus.pages[0].transform,m.weatherPresets,new Vector2(0,286));foreach(var text in m.menus.pages[0].GetComponentsInChildren<TMP_Text>(true))if(text.name=="Weather selection label"||text.name=="Weather selection explanation")text.gameObject.SetActive(false);var display=m.menus.GetComponent<CornholeWindDisplay>();if(display==null){display=m.menus.gameObject.AddComponent<CornholeWindDisplay>();display.match=m;display.arrows=new RectTransform[4];display.speeds=new TMP_Text[4];for(int i=0;i<4;i++){var panel=SportsUIAuthoring.Rect("Actual flight wind · course "+i,m.menus.views[i],new Vector2(218,76),Vector2.zero);var rect=panel.GetComponent<RectTransform>();rect.anchorMin=rect.anchorMax=rect.pivot=new Vector2(1,0);rect.anchoredPosition=new Vector2(-8,7);var image=panel.AddComponent<UnityEngine.UI.Image>();image.color=SportsBroadcastCanvas.Ink;image.raycastTarget=false;panel.AddComponent<SportsBroadcastPlate>();var arrow=SportsUIAuthoring.Rect("Wind blows relative to approach",panel.transform,new Vector2(34,34),new Vector2(-76,0));display.arrows[i]=arrow.GetComponent<RectTransform>();Arrow(arrow.transform,"Stem",new Vector2(0,-3),new Vector2(5,30),0);Arrow(arrow.transform,"Left head",new Vector2(-5,8),new Vector2(5,18),-40);Arrow(arrow.transform,"Right head",new Vector2(5,8),new Vector2(5,18),40);display.speeds[i]=SportsUIAuthoring.Text("Authoritative wind MPH",panel.transform,"WIND",new Vector2(150,66),new Vector2(23,0),22);var footer=m.menus.footers[i].rectTransform;footer.offsetMax=new Vector2(-232,footer.offsetMax.y);}}EditorUtility.SetDirty(m);EditorUtility.SetDirty(display);}
 static void Arrow(Transform parent,string name,Vector2 position,Vector2 size,float angle){var part=SportsUIAuthoring.Rect(name,parent,size,position);part.transform.localRotation=Quaternion.Euler(0,0,angle);var image=part.AddComponent<UnityEngine.UI.Image>();image.color=new Color(.4f,.93f,.9f);image.raycastTarget=false;}
}
}
